"""Review-gated project visual-rule candidates generated by local Qwen.

Only authored project, style, episode-summary and Bible text is sent to the
text-only runtime.  Generation never mutates the project.  The explicit apply
step re-locks the project, verifies the source fingerprint and atomically
updates only the three existing project-owned visual-rule fields.
"""
from __future__ import annotations

import hashlib
import hmac
import json
import re
from typing import Any

from django.db import transaction

from studio.models import GenerationTask, SeriesProject
from studio.services.prompt_translation import (
    PromptTranslationError,
    PromptTranslationResourceBusy,
    _config as local_qwen_config,
    _require_runtime as require_local_qwen_runtime,
    _run_runtime as run_local_qwen_runtime,
)


VISUAL_RULE_DRAFT_OPERATION = "project_visual_rules_draft"
VISUAL_RULE_DRAFT_SCHEMA_VERSION = 1
VISUAL_RULE_DRAFT_MAX_SOURCE_CHARS = 16_000
_CJK_RE = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff]")
_HTML_RE = re.compile(r"<\/?[A-Za-z][^>]*>")
_ACTIVE_TASK_STATUSES = (
    GenerationTask.Status.QUEUED,
    GenerationTask.Status.RUNNING,
    GenerationTask.Status.CANCEL_REQUESTED,
)
_PLATFORM_NEGATIVE_CLAUSES = (
    "identity drift",
    "face drift",
    "age drift",
    "hairstyle change",
    "wardrobe change",
    "prop mutation",
    "inconsistent architecture",
    "duplicate person",
    "extra limbs",
    "extra fingers",
    "deformed hands",
    "readable text",
    "subtitles",
    "watermark",
    "logo",
    "flicker",
    "jitter",
    "camera teleport",
    "low detail",
)
COLOR_VALUES = (
    "black", "charcoal", "gray", "slate", "ivory", "white", "brown", "sepia",
    "navy", "blue", "cyan", "teal", "green", "amber", "gold", "copper", "orange",
    "red", "crimson", "magenta", "violet",
)
COLOR_DESIGN_CHOICES = {
    "accent_color": (*COLOR_VALUES, "none"),
    "palette_relation": (
        "monochromatic", "analogous", "complementary", "neutral", "cinematic",
    ),
    "lighting": (
        "soft_diffuse", "hard_directional", "low_key", "high_key", "practical",
        "volumetric", "rim_accent", "balanced_ambient",
    ),
    "contrast": ("low", "restrained", "medium", "high"),
    "saturation": ("desaturated", "muted", "natural", "selective", "saturated"),
    "exposure": ("dark", "balanced", "bright"),
    "progression": (
        "stable", "cool_to_warm", "warm_to_cool", "dark_to_bright",
        "bright_to_dark", "muted_to_saturated", "saturated_to_muted",
    ),
}
COLOR_DESIGN_FIELDS = frozenset({
    "base_colors", "accent_color", "palette_relation", "lighting", "contrast",
    "saturation", "exposure", "progression", "preserve_natural_skin_exposure",
})
_LIGHTING_LABELS = {
    "soft_diffuse": "soft diffuse",
    "hard_directional": "hard directional",
    "low_key": "low-key",
    "high_key": "high-key",
    "practical": "practical",
    "volumetric": "volumetric",
    "rim_accent": "controlled rim accent",
    "balanced_ambient": "balanced ambient",
}
_PROGRESSION_LABELS = {
    "stable": "remains stable",
    "cool_to_warm": "shifts gradually from cool to warm",
    "warm_to_cool": "shifts gradually from warm to cool",
    "dark_to_bright": "shifts gradually from dark to bright",
    "bright_to_dark": "shifts gradually from bright to dark",
    "muted_to_saturated": "shifts gradually from muted to saturated",
    "saturated_to_muted": "shifts gradually from saturated to muted",
}
_NEGATIVE_DEFECT_RE = re.compile(
    r"\b(?:drift|change|mutation|inconsistent|duplicate|extra|deformed|malformed|"
    r"blur(?:ry)?|watermark|logo|text|subtitles?|flicker|jitter|teleport|"
    r"low detail|noise|artifacts?|oversaturated|underexposed|overexposed)\b",
    re.IGNORECASE,
)
_NEGATIVE_MARKER_RE = re.compile(
    r"^(?:no|without|avoid|exclude|prevent|do not|never)\b",
    re.IGNORECASE,
)
_NEGATIVE_POSITIVE_VISUAL_RE = re.compile(
    r"\b(?:color|palette|light|lighting|shadow|highlight|tone|contrast|saturation|"
    r"exposure|quality|high detail|natural skin|warm|cool)\b",
    re.IGNORECASE,
)


class VisualRuleDraftError(RuntimeError):
    pass


class VisualRuleDraftValidationError(VisualRuleDraftError):
    pass


class VisualRuleDraftResourceBusy(VisualRuleDraftError):
    pass


class VisualRuleDraftRuntimeUnavailable(VisualRuleDraftError):
    pass


class VisualRuleDraftConflict(VisualRuleDraftError):
    pass


def _text(value: Any) -> str:
    return str(value or "").strip()


def visual_rule_context_snapshot(project: SeriesProject) -> dict[str, Any]:
    """Return every authoritative source field covered by the fingerprint."""
    settings = project.production_settings if isinstance(project.production_settings, dict) else {}
    glossary = settings.get("translation_glossary")
    if not isinstance(glossary, dict):
        glossary = {}
    glossary = {
        _text(source): _text(target)
        for source, target in glossary.items()
        if _text(source) and _text(target)
    }
    style = project.style
    return {
        "schema_version": VISUAL_RULE_DRAFT_SCHEMA_VERSION,
        "project": {
            "id": str(project.id),
            "title": project.title,
            "logline": project.logline,
            "master_script": project.master_script,
            "language": project.language,
            "aspect_ratio": project.aspect_ratio,
            "width": project.width,
            "height": project.height,
            "target_model": project.target_model,
            "continuity_summary": project.continuity_summary,
        },
        "production_settings": {
            "negative_prompt": _text(settings.get("negative_prompt")),
            "color_script": _text(settings.get("color_script")),
            "translation_glossary": glossary,
            "default_h3_mode": _text(settings.get("default_h3_mode")),
        },
        "style": ({
            "id": str(style.id),
            "name": style.name,
            "category": style.category,
            "description": style.description,
            "visual_prompt": style.visual_prompt,
            "negative_prompt": style.negative_prompt,
        } if style else None),
        "episodes": [{
            "number": item.number,
            "title": item.title,
            "synopsis": item.synopsis,
        } for item in project.episodes.order_by("number").only("number", "title", "synopsis")],
        "bible": {
            "characters": [{
                "id": str(item.id),
                "stable_speaker_id": item.stable_speaker_id,
                "name": item.name,
                "role": item.role,
                "description": item.description,
                "visual_identity": item.visual_identity,
                "negative_constraints": item.negative_constraints,
                "age_appearance": item.age_appearance,
                "face_identity": item.face_identity,
                "wardrobe": item.wardrobe,
            } for item in project.characters.order_by("stable_speaker_id")],
            "scenes": [{
                "id": str(item.id),
                "name": item.name,
                "description": item.description,
                "visual_identity": item.visual_identity,
                "negative_constraints": item.negative_constraints,
                "location": item.location,
                "time_of_day": item.time_of_day,
                "lighting": item.lighting,
                "color_palette": item.color_palette,
            } for item in project.scenes.order_by("slug")],
            "props": [{
                "id": str(item.id),
                "name": item.name,
                "description": item.description,
                "visual_identity": item.visual_identity,
                "negative_constraints": item.negative_constraints,
                "material": item.material,
                "distinctive_marks": item.distinctive_marks,
                "continuity_state": item.continuity_state,
            } for item in project.props.order_by("slug")],
        },
    }


def visual_rule_context_fingerprint(project: SeriesProject) -> str:
    return _snapshot_fingerprint(visual_rule_context_snapshot(project))


def _snapshot_fingerprint(snapshot: dict[str, Any]) -> str:
    encoded = json.dumps(
        snapshot, ensure_ascii=False,
        sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _generation_fingerprint(
    *, context_fingerprint: str, attempt: int, direction_note: str, variation_note: str,
) -> str:
    encoded = json.dumps({
        "context_fingerprint": context_fingerprint,
        "attempt": attempt,
        "direction_note": direction_note,
        "variation_note": variation_note,
    }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _split_negative_clauses(value: str) -> list[str]:
    return [part.strip(" .") for part in re.split(r"[,;\n]+", value) if part.strip(" .")]


def _negative_prompt(snapshot: dict[str, Any]) -> tuple[str, set[str], list[str]]:
    clauses = list(_PLATFORM_NEGATIVE_CLAUSES)
    warnings: list[str] = []
    sources: list[str] = [_text(snapshot["production_settings"].get("negative_prompt"))]
    if snapshot["style"]:
        sources.append(_text(snapshot["style"].get("negative_prompt")))
    for collection in snapshot["bible"].values():
        sources.extend(_text(item.get("negative_constraints")) for item in collection)
    skipped = 0
    protected = [value.casefold() for value in _protected_names(snapshot) if value]
    for source in sources:
        for clause in _split_negative_clauses(source):
            # Only exact, already-English defect phrases are merged. Chinese or
            # narrative constraints remain visible as a warning instead of
            # being freely re-authored by the model.
            folded = clause.casefold()
            if (
                not clause.isascii() or len(clause) > 120 or _HTML_RE.search(clause)
                or _NEGATIVE_POSITIVE_VISUAL_RE.search(clause)
                or not (
                    _NEGATIVE_DEFECT_RE.search(clause) or _NEGATIVE_MARKER_RE.search(clause)
                )
                or any(name in folded for name in protected)
            ):
                skipped += 1
                continue
            if clause and folded not in {item.casefold() for item in clauses}:
                clauses.append(clause)
    if skipped:
        warnings.append(
            f"{skipped} 条中文、叙事性或不安全负面约束未自动并入；请人工审核后另行补充英文短语。"
        )
    allowed = {item.casefold() for item in clauses}
    return ", ".join(clauses), allowed, warnings


def _deterministic_continuity_summary(snapshot: dict[str, Any]) -> str:
    clauses = [
        "Maintain consistent project-wide visual style, rendering treatment, and environmental logic across episodes."
    ]
    if snapshot["bible"]["characters"]:
        clauses.append(
            "Preserve character identity, facial features, age appearance, hairstyle, and wardrobe exactly as defined in the Character Bible."
        )
    if snapshot["bible"]["scenes"]:
        clauses.append(
            "Preserve scene architecture, spatial layout, lighting logic, and environmental continuity exactly as defined in the Scene Bible."
        )
    if snapshot["bible"]["props"]:
        clauses.append(
            "Preserve prop shape, material, scale, distinctive marks, and state exactly as defined in the Prop Bible."
        )
    return " ".join(clauses)


def _protected_names(snapshot: dict[str, Any]) -> list[str]:
    names = [_text(snapshot["project"].get("title"))]
    for collection in snapshot["bible"].values():
        names.extend(_text(item.get("name")) for item in collection)
    glossary = snapshot["production_settings"].get("translation_glossary") or {}
    names.extend(_text(value) for value in glossary.values())
    return sorted({name for name in names if len(name) >= 2}, key=str.casefold)


def validate_color_design(value: Any) -> dict[str, Any]:
    """Fail closed on the complete model/user-supplied structured design."""
    if not isinstance(value, dict) or set(value) != COLOR_DESIGN_FIELDS:
        raise VisualRuleDraftValidationError("color_design 字段不完整或含不支持的字段")
    base_colors = value.get("base_colors")
    if not isinstance(base_colors, list) or not 1 <= len(base_colors) <= 3:
        raise VisualRuleDraftValidationError("color_design.base_colors 必须包含 1 至 3 个颜色")
    if any(not isinstance(item, str) or item not in COLOR_VALUES for item in base_colors):
        raise VisualRuleDraftValidationError("color_design.base_colors 含不支持的枚举值")
    if len(set(base_colors)) != len(base_colors):
        raise VisualRuleDraftValidationError("color_design.base_colors 不能重复")
    result: dict[str, Any] = {"base_colors": list(base_colors)}
    for field, choices in COLOR_DESIGN_CHOICES.items():
        item = value.get(field)
        if not isinstance(item, str) or item not in choices:
            raise VisualRuleDraftValidationError(f"color_design.{field} 含不支持的枚举值")
        result[field] = item
    preserve = value.get("preserve_natural_skin_exposure")
    if type(preserve) is not bool:
        raise VisualRuleDraftValidationError(
            "color_design.preserve_natural_skin_exposure 必须是布尔值"
        )
    result["preserve_natural_skin_exposure"] = preserve
    return result


def _join_color_names(values: list[str]) -> str:
    if len(values) == 1:
        return values[0]
    if len(values) == 2:
        return f"{values[0]} and {values[1]}"
    return f"{values[0]}, {values[1]}, and {values[2]}"


def render_color_script(color_design: Any) -> str:
    """The only renderer used for preview and apply; never accepts free prose."""
    design = validate_color_design(color_design)
    accent = (
        "no separate accent color"
        if design["accent_color"] == "none"
        else f"a selective {design['accent_color']} accent"
    )
    progression = _PROGRESSION_LABELS[design["progression"]]
    skin_sentence = (
        "Natural skin exposure remains balanced."
        if design["preserve_natural_skin_exposure"]
        else "Skin exposure follows the selected overall exposure."
    )
    return (
        f"The series uses a {design['palette_relation']} palette built from "
        f"{_join_color_names(design['base_colors'])}, with {accent}. "
        f"The lighting treatment is {_LIGHTING_LABELS[design['lighting']]}, "
        f"contrast is {design['contrast']}, saturation is {design['saturation']}, "
        f"and exposure is {design['exposure']}. Across episodes, the palette "
        f"{progression}. {skin_sentence}"
    )


def _visual_rule_candidate(
    *, color_design: Any, negative_prompt: str, continuity_summary: str,
) -> tuple[dict[str, Any], dict[str, str]]:
    design = validate_color_design(color_design)
    return design, {
        "negative_prompt": negative_prompt,
        "color_script": render_color_script(design),
        "continuity_summary": continuity_summary,
    }


def _runtime_context(snapshot: dict[str, Any]) -> dict[str, Any]:
    # UUIDs are fingerprint evidence but add no authored visual meaning.
    copy = json.loads(json.dumps(snapshot, ensure_ascii=False))
    copy["project"].pop("id", None)
    if copy.get("style"):
        copy["style"].pop("id", None)
    for collection in copy["bible"].values():
        for item in collection:
            item.pop("id", None)
    return copy


def generate_visual_rule_draft(
    *, project: SeriesProject, user, attempt: int = 1, direction_note: str = "",
    variation_note: str = "", expected_context_fingerprint: str = "",
) -> dict[str, Any]:
    if project.owner_id != user.id and not user.is_staff:
        raise VisualRuleDraftValidationError("不能为其他用户的项目生成全剧视觉规则")
    attempt = max(1, min(int(attempt), 100))
    direction_note = _text(direction_note)
    variation_note = _text(variation_note)
    snapshot = visual_rule_context_snapshot(project)
    context_fingerprint = _snapshot_fingerprint(snapshot)
    if expected_context_fingerprint and not hmac.compare_digest(
        context_fingerprint, expected_context_fingerprint,
    ):
        raise VisualRuleDraftConflict("项目说明、剧集摘要、风格或 Bible 已变化，请基于最新内容重新生成")
    context = _runtime_context(snapshot)
    source_size = len(json.dumps(context, ensure_ascii=False, separators=(",", ":")))
    if source_size > VISUAL_RULE_DRAFT_MAX_SOURCE_CHARS:
        raise VisualRuleDraftValidationError(
            f"全剧视觉规则上下文共 {source_size} 字符，超过本地模型 {VISUAL_RULE_DRAFT_MAX_SOURCE_CHARS} 字符上限；请精简母稿或 Bible 描述"
        )
    if GenerationTask.objects.filter(status__in=_ACTIVE_TASK_STATUSES).exists():
        raise VisualRuleDraftResourceBusy("视频任务正在排队或执行；请等待完成后再调用本地 Qwen")

    negative_prompt, _allowed_negative, warnings = _negative_prompt(snapshot)
    continuity_summary = _deterministic_continuity_summary(snapshot)
    generation_fingerprint = _generation_fingerprint(
        context_fingerprint=context_fingerprint, attempt=attempt,
        direction_note=direction_note, variation_note=variation_note,
    )
    config = local_qwen_config()
    try:
        require_local_qwen_runtime(config)
        runtime_payload = run_local_qwen_runtime({
            "operation": VISUAL_RULE_DRAFT_OPERATION,
            "request_id": generation_fingerprint[:24],
            "source_fingerprint": context_fingerprint,
            "context": context,
            "attempt": attempt,
            "direction_note": direction_note,
            "variation_note": variation_note,
            "seed": int(generation_fingerprint[:8], 16),
            "model_dir": str(config["model_dir"]),
            "model_id": config["model_id"],
            "device": config["device"],
            "gpu_layers": config.get("gpu_layers", -1),
            "max_new_tokens": 512,
            "context_size": 8_192,
            "timeout_seconds": config["timeout_seconds"],
        }, config)
    except PromptTranslationResourceBusy as exc:
        raise VisualRuleDraftResourceBusy(str(exc)) from exc
    except PromptTranslationError as exc:
        raise VisualRuleDraftRuntimeUnavailable(str(exc)) from exc

    runtime_result = runtime_payload.get("result")
    if not isinstance(runtime_result, dict) or set(runtime_result) != {"color_design"}:
        raise VisualRuleDraftValidationError("本地 Qwen 返回的 color_design 结构无效")
    color_design, candidate = _visual_rule_candidate(
        color_design=runtime_result["color_design"],
        negative_prompt=negative_prompt,
        continuity_summary=continuity_summary,
    )
    current = SeriesProject.objects.select_related("style").get(pk=project.pk)
    if not hmac.compare_digest(context_fingerprint, visual_rule_context_fingerprint(current)):
        raise VisualRuleDraftConflict("项目源内容在生成期间发生变化，请刷新后重新生成")
    metadata = runtime_payload.get("metadata") if isinstance(runtime_payload.get("metadata"), dict) else {}
    return {
        "project_id": str(project.id),
        "context_fingerprint": context_fingerprint,
        "context_current": True,
        "candidate_language": "en",
        "review_required": True,
        "persisted": False,
        "color_design": color_design,
        "draft": candidate,
        "field_modes": {
            "negative_prompt": "deterministic_guard",
            "color_script": "structured_design",
            "continuity_summary": "deterministic_guard",
        },
        "warnings": warnings,
        "source_summary": {
            "project_fields": [
                "title", "logline", "master_script", "language", "aspect_ratio",
                "width", "height", "target_model", "continuity_summary",
            ],
            "production_setting_fields": [
                "negative_prompt", "color_script", "translation_glossary", "default_h3_mode",
            ],
            "style_included": snapshot["style"] is not None,
            "character_count": len(snapshot["bible"]["characters"]),
            "scene_count": len(snapshot["bible"]["scenes"]),
            "prop_count": len(snapshot["bible"]["props"]),
            "episode_summary_count": len(snapshot["episodes"]),
            "episode_scripts_included": False,
            "shots_included": False,
        },
        "generation": {
            "attempt": attempt,
            "direction_note_provided": bool(direction_note),
            "variation_note_provided": bool(variation_note),
            "generation_fingerprint": generation_fingerprint,
        },
        "runtime": {
            "provider": "local_qwen",
            "model": str(runtime_payload.get("model") or config["model_id"]),
            "loaded_on_demand": True,
            "unloaded_after_request": True,
            "review_required": True,
            "persisted": False,
            "elapsed_ms": runtime_payload.get("elapsed_ms"),
            "repair_attempted": bool(metadata.get("repair_attempted")),
            "repair_succeeded": bool(metadata.get("repair_succeeded")),
        },
    }


def apply_visual_rule_draft(
    *, project: SeriesProject, user, context_fingerprint: str,
    color_design: dict[str, Any], attempt: int, direction_note: str,
    variation_note: str, generation_fingerprint: str,
) -> dict[str, Any]:
    if project.owner_id != user.id and not user.is_staff:
        raise VisualRuleDraftValidationError("不能修改其他用户的项目")
    direction_note = _text(direction_note)
    variation_note = _text(variation_note)
    with transaction.atomic():
        locked = SeriesProject.objects.select_for_update().select_related("style").get(pk=project.pk)
        # Project Bible synchronization also locks the project row. Lock the
        # existing related source rows here so the fingerprint and write share
        # one stable authoritative snapshot.
        list(locked.characters.select_for_update().only("id"))
        list(locked.scenes.select_for_update().only("id"))
        list(locked.props.select_for_update().only("id"))
        list(locked.episodes.select_for_update().only("id"))
        snapshot = visual_rule_context_snapshot(locked)
        current_fingerprint = _snapshot_fingerprint(snapshot)
        if not hmac.compare_digest(current_fingerprint, context_fingerprint):
            raise VisualRuleDraftConflict("项目源内容已变化，旧候选不能应用；请重新生成")
        expected_generation = _generation_fingerprint(
            context_fingerprint=context_fingerprint, attempt=attempt,
            direction_note=direction_note, variation_note=variation_note,
        )
        if not hmac.compare_digest(expected_generation, generation_fingerprint):
            raise VisualRuleDraftConflict("候选的生成方向或重生成反馈不匹配，请重新生成")
        default_negative, _allowed_negative, _warnings = _negative_prompt(snapshot)
        default_continuity = _deterministic_continuity_summary(snapshot)
        _validated_design, candidate = _visual_rule_candidate(
            color_design=color_design,
            negative_prompt=default_negative,
            continuity_summary=default_continuity,
        )
        settings = dict(locked.production_settings or {})
        settings["negative_prompt"] = candidate["negative_prompt"]
        settings["color_script"] = candidate["color_script"]
        locked.production_settings = settings
        locked.continuity_summary = candidate["continuity_summary"]
        locked.save(update_fields=("production_settings", "continuity_summary", "updated_at"))
        applied_at = locked.updated_at
        next_fingerprint = visual_rule_context_fingerprint(locked)
    return {
        "project_id": str(project.id),
        "applied_context_fingerprint": context_fingerprint,
        "current_context_fingerprint": next_fingerprint,
        "updated_at": applied_at,
        "applied": candidate,
    }
